    try{ doc.applyFauxBold = true; }catch(e){}
    doc.fillColor = [1,1,1];
    try{ doc.tracking = 30; }catch(e){}
    try{ doc.justification = ParagraphJustification.CENTER_JUSTIFY; }catch(e){}

    var L = comp.layers.addText(doc);
    L.name = "S"+(sc.idx+1)+"_"+word;
    L.threeDLayer = true;
    var tp = L.property("ADBE Text Properties");
    // position & anchor to visual center
    var posP = gp(L, ["ADBE Position","Position"]);
    posP.setValue([W/2 + xA, yA, zLane]);
    try{
      var rect = L.sourceRectAtTime(t0+0.6, false);
      gp(L, ["ADBE Anchor Point","Anchor Point"]).setValue([rect.left + rect.width/2, rect.top + rect.height/2, 0]);
    }catch(e){ logit("anchor fail "+L.name+" "+e); }

    // scale punch-in + beat pump
    gp(L, ["ADBE Scale","Scale"]).expression =
      "var t0=" + t0.toFixed(3) + "; var e=clamp((time-t0)/0.22,0,1); e=1-Math.pow(1-e,4);" +
      "var a=thisComp.layer('AUD').effect('Audio Amplitude')('Slider'); var s=(150-50*e)*(1+a*0.0013); [s,s,s];";
    // fade in / out
    gp(L, ["ADBE Opacity","Opacity"]).expression =
      "var t0=" + t0.toFixed(3) + ", t1=" + t1.toFixed(3) + ";" +
      "var i0=clamp((time-t0)/0.12,0,1); var o1=clamp((t1-time)/0.14,0,1); 100*Math.min(i0,o1);";
    // settle rotation
    gp(L, ["ADBE Rotate Y","Y Rotation"]).expression =
      "var t0=" + t0.toFixed(3) + "; var e=clamp((time-t0)/0.25,0,1); e=1-Math.pow(1-e,4); value - 10*(1-e);";
    gp(L, ["ADBE Rotate Z","Z Rotation"]).expression =
      "var a=thisComp.layer('AUD').effect('Audio Amplitude')('Slider'); value - a*0.02 + " + (j%2===0? 3:-3) + ";";
    // slow z drift forward
    gp(L, ["ADBE Position","Position"]).expression =
      "value + [0, 0, Math.min(220, Math.max(0, time-" + t0.toFixed(3) + ")*30)];";
    // slight 3D offset between words for depth collage
    gp(L, ["ADBE Orientation","Orientation"]).setValue([ (j%2===0? -8:-14), (j%2===0? 10:16), 0]);

